mapper.select:
SELECT COUNT(*)
  FROM SKT0HS
 WHERE CORP_GR = #{corpGr}
   AND TR_YMD  = #{trYmd}
   AND FUND_CD = #{fundCd}
   AND TR_CD   = #{trCd}

mapper.insert:
INSERT INTO SKT0HS (
    CORP_GR
  , TR_YMD
  , FUND_CD
  , TR_CD
  , TR_CO_CD
  , HWANIB_AEK
  , BAL_AEK
  , BF_YMD
  , AF_YMD
  , BIGO
) VALUES (
    #{corpGr}
  , #{trYmd}
  , #{fundCd}
  , #{trCd}
  , #{trCoCd, jdbcType=VARCHAR}
  , NVL(#{hwanibAek, jdbcType=NUMERIC}, 0)
  , NVL(#{balAek, jdbcType=NUMERIC}, 0)
  , #{bfYmd, jdbcType=DATE}
  , #{afYmd, jdbcType=DATE}
  , #{bigo, jdbcType=VARCHAR}
)

mapper.update:
UPDATE SKT0HS
   SET HWANIB_AEK = NVL(#{hwanibAek, jdbcType=NUMERIC}, 0)
     , BIGO       = #{bigo, jdbcType=VARCHAR}

     , TR_CO_CD   = #{trCoCd}

 WHERE CORP_GR    = #{corpGr}
   AND TR_YMD     = #{trYmd}
   AND FUND_CD    = COALESCE(#{originalFundCd}, #{fundCd})
   AND TR_CD      = #{trCd}

mapper.delete:
DELETE FROM SKT0HS
 WHERE CORP_GR = #{corpGr}
   AND TR_YMD  = #{trYmd}
   AND FUND_CD = #{fundCd}
   AND TR_CD   = #{trCd}
